        value.to_s
      when ::BigDecimal
        raise ::ArgumentError, 'cannot bind a non-finite BigDecimal to MySQL' unless value.finite?

        value.to_s('F')
      when ::DateTime, ::Time
        "'#{mysql_time(client, value)}'"
      when ::Date
        "'#{value.strftime('%Y-%m-%d')}'"
      when ::String
